import{_ as l,a0 as p,w as d,s as o,I as a,x as i,a1 as n,A as t,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"自動解鎖 Linux 上的加密磁盤 | LCTT x X-CMD","titleTemplate":false,"description":"自動解鎖 Linux 上的加密磁盤 | LCTT (202011) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"自動解鎖 Linux 上的加密磁盤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"自動解鎖 Linux 上的加密磁盤 | LCTT (202011) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202011/20201116 Unlock encrypted disks on Linux automatically","title":"自動解鎖 Linux 上的加密磁盤","tag":"202011","desc":""},"relativePath":"202011/20201116 Unlock encrypted disks on Linux automatically.md","filePath":"[post].md"}'),h={name:"202011/20201116 Unlock encrypted disks on Linux automatically.md"};function g(c,s,u,k,b,f){const e=p("Link");return d(),o("div",null,[s[27]||(s[27]=a("h1",{id:"自動解鎖-linux-上的加密磁盤",tabindex:"-1"},[i("自動解鎖 Linux 上的加密磁盤 "),a("a",{class:"header-anchor",href:"#自動解鎖-linux-上的加密磁盤","aria-label":"Permalink to “自動解鎖 Linux 上的加密磁盤”"},"​")],-1)),s[28]||(s[28]=a("blockquote",null,[a("p",null,"通過使用網絡綁定磁盤加密（NBDE），無需手動輸入密碼即可打開加密磁盤。")],-1)),s[29]||(s[29]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202011/23/104735lmx18sxxs18f4xcc.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=i("從安全的角度來看，對敏感數據進行加密以保護其免受窺探和黑客的攻擊是很重要的。",-1)),s[2]||(s[2]=a("ruby",null,[i("Linux 統一密鑰設置"),a("rt",null,"Linux Unified Key Setup")],-1)),s[3]||(s[3]=i("（",-1)),n(e,{href:"https://en.wikipedia.org/wiki/Linux_Unified_Key_Setup"},{default:t(()=>[...s[0]||(s[0]=[i("LUKS",-1)])]),_:1}),s[4]||(s[4]=i("）是一個很好的工具，也是 Linux 磁盤加密的通用標準。因為它將所有相關的設置信息存儲在分區頭部中，所以它使數據遷移變得簡單。",-1))]),a("p",null,[s[6]||(s[6]=i("要使用 LUKS 配置加密磁盤或分區，你需要使用 ",-1)),n(e,{href:"https://gitlab.com/cryptsetup/cryptsetup"},{default:t(()=>[...s[5]||(s[5]=[i("cryptsetup",-1)])]),_:1}),s[7]||(s[7]=i(" 工具。不幸的是，加密磁盤的一個缺點是，每次系統重啓或磁盤重新掛載時，你都必須手動提供密碼。",-1))]),s[30]||(s[30]=a("p",null,[i("然而，"),a("ruby",null,[i("網絡綁定磁盤加密"),a("rt",null,"Network-Bound Disk Encryption")]),i("（NBDE） 可以在沒有任何用户干預的情況下自動安全地解鎖加密磁盤。它可以在一些 Linux 發行版中使用，包括從 Red Hat Enterprise Linux 7.4、CentOS 7.4 和 Fedora 24 開始，以及之後的後續版本。")],-1)),s[31]||(s[31]=a("p",null,"NBDE 採用以下技術實現：",-1)),a("ul",null,[a("li",null,[n(e,{href:"https://github.com/latchset/clevis"},{default:t(()=>[...s[8]||(s[8]=[i("Clevis 框架",-1)])]),_:1}),s[9]||(s[9]=i("：一個可插拔的框架工具，可自動解密和解鎖 LUKS 卷",-1))]),a("li",null,[n(e,{href:"https://github.com/latchset/tang"},{default:t(()=>[...s[10]||(s[10]=[i("Tang 服務器",-1)])]),_:1}),s[11]||(s[11]=i("：用於將加密密鑰綁定到網絡狀態的服務",-1))])]),s[32]||(s[32]=r(`<p>Tang 向 Clevis 客户端提供加密密鑰。據 Tang 的開發人員介紹，這為密鑰託管服務提供了一個安全、無狀態、匿名的替代方案。</p><p>由於 NBDE 使用客户端-服務器架構，你必須同時配置客户端和服務器。你可以在你的本地網絡上使用一個虛擬機作為 Tang 服務器。</p><h3 id="服務器安裝" tabindex="-1">服務器安裝 <a class="header-anchor" href="#服務器安裝" aria-label="Permalink to “服務器安裝”">​</a></h3><p>用 sudo 安裝 Tang：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo yum install tang -y</span></span></code></pre></div><p>啓用 Tang 服務器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl enable tangd.socket --now</span></span></code></pre></div><p>Tang 服務器工作在 80 端口，需加入到 firewalld 防火牆。添加相應的 firewalld 規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo  firewall-cmd --add-port=tcp/80 --perm</span></span>
<span class="line"><span>sudo firewall-cmd --reload</span></span></code></pre></div><p>現在安裝好了服務器。</p><h3 id="客户端安裝" tabindex="-1">客户端安裝 <a class="header-anchor" href="#客户端安裝" aria-label="Permalink to “客户端安裝”">​</a></h3><p>在本例中，假設你已經添加了一個名為 <code>/dev/vdc</code> 的新的 1GB 磁盤到你的系統中。</p><p>使用 <code>fdisk</code> 或 <code>parted</code> 創建主分區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo fdisk /dev/vdc</span></span></code></pre></div><p>完成以下步驟來安裝客户端：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Welcome to fdisk (util-linux 2.23.2).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Changes will remain in memory only, until you decide to write them.</span></span>
<span class="line"><span>Be careful before using the write command.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Device does not contain a recognized partition table</span></span>
<span class="line"><span>Building a new DOS disklabel with disk identifier 0x4a6812d4.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Command (m for help):</span></span></code></pre></div><p>輸入 <code>n</code> 來創建新的分區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Partition type:</span></span>
<span class="line"><span>   p   primary (0 primary, 0 extended, 4 free)</span></span>
<span class="line"><span>   e   extended  </span></span>
<span class="line"><span>Select (default p):</span></span></code></pre></div><p>按下<strong>回車</strong>鍵選擇主分區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Using default response p</span></span>
<span class="line"><span>Partition number (1-4, default 1):</span></span></code></pre></div><p>按下回車鍵選擇默認分區號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>First sector (2048-2097151, default 2048):</span></span>
<span class="line"><span>Using default value 2048</span></span>
<span class="line"><span>Last sector, +sectors or +size{K,M,G} (2048-2097151, default 2097151):</span></span></code></pre></div><p>按回車鍵選擇最後一個扇區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Using default value 2097151</span></span>
<span class="line"><span>Partition 1 of type Linux and of size 1023 MiB is set</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Command (m for help): wq</span></span></code></pre></div><p>輸入 <code>wq</code> 保存更改並退出 <code>fdisk</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>The partition table has been altered!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Calling ioctl() to re-read partition table.</span></span>
<span class="line"><span>Syncing disks.</span></span></code></pre></div><p>運行 <code>partprobe</code> 通知系統分區表的變化：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo partprobe</span></span></code></pre></div><p>使用 <code>sudo</code> 安裝 cryptsetup 軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo yum install cryptsetup -y</span></span></code></pre></div><p>使用 <code>cryptsetup luksFormat</code> 命令對磁盤進行加密。當提示時，你需要輸入大寫的 <code>YES</code>，並輸入密碼來加密磁盤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cryptsetup luksFormat /dev/vdc1</span></span>
<span class="line"><span>WARNING!</span></span>
<span class="line"><span>========</span></span>
<span class="line"><span>This will overwrite data on /dev/vdc1 irrevocably.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Are you sure? (Type uppercase yes):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Enter passphrase for /dev/vdc1:</span></span>
<span class="line"><span>Verify passphrase:</span></span></code></pre></div><p>使用 <code>cryptsetup luksOpen</code> 命令將加密的分區映射到一個邏輯設備上。例如，使用 <code>encryptedvdc1</code> 作為名稱。你還需要再次輸入密碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cryptsetup luksOpen /dev/vdc1 encryptedvdc1</span></span>
<span class="line"><span>Enter passphrase for /dev/vdc1:</span></span></code></pre></div><p>加密分區現在在 <code>/dev/mapper/encryptedvdc1</code> 中可用。</p><p>在加密的分區上創建一個 XFS 文件系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mkfs.xfs /dev/mapper/encryptedvdc1</span></span></code></pre></div><p>創建一個掛載加密分區的目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mkdir /encrypted</span></span></code></pre></div><p>使用 <code>cryptsetup luksClose</code> 命令鎖定分區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cryptsetup luksClose encryptedvdc1</span></span></code></pre></div><p>使用 <code>sudo</code> 安裝 Clevis 軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo yum install clevis clevis-luks clevis-dracut -y</span></span></code></pre></div><p>修改 <code>/etc/crypttab</code>，在啓動時打開加密卷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo vim /etc/crypttab</span></span></code></pre></div><p>增加以下一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>encryptedvdc1       /dev/vdc1  none   _netdev</span></span></code></pre></div><p>修改 <code>/etc/fstab</code>，在重啓時或啓動時自動掛載加密卷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo vim /etc/fstab</span></span></code></pre></div><p>增加以下一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/dev/mapper/encryptedvdc1   /encrypted       xfs    _netdev        1 2</span></span></code></pre></div><p>在這個例子中，假設 Tang 服務器的 IP 地址是 <code>192.168.1.20</code>。如果你喜歡，也可以使用主機名或域名。</p><p>運行以下 <code>clevis</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo clevis bind luks -d /dev/vdc1 tang &#39;{&quot;url&quot;:&quot;http://192.168.1.20&quot;}&#39;</span></span>
<span class="line"><span>The advertisement contains the following signing keys:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>rwA2BAITfYLuyNiIeYUMBzkhk7M</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do you wish to trust these keys? [ynYN] Y</span></span>
<span class="line"><span>Enter existing LUKS password:</span></span></code></pre></div><p>輸入 <code>Y</code> 接受 Tang 服務器的密鑰，並提供現有的 LUKS 密碼進行初始設置。</p><p>通過 <code>systemctl</code> 啓用 <code>clevis-luks-askpass.path</code>，以防止非根分區被提示輸入密碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl enable clevis-luks-askpass.path</span></span></code></pre></div><p>客户端已經安裝完畢。現在，每當你重啓服務器時，加密後的磁盤應該會自動解密，並通過 Tang 服務器取回密鑰進行掛載。</p><p>如果 Tang 服務器因為任何原因不可用，你需要手動提供密碼，才能解密和掛載分區。</p><hr>`,60)),a("p",null,[s[13]||(s[13]=i("via: ",-1)),n(e,{href:"https://opensource.com/article/20/11/nbde-linux"},{default:t(()=>[...s[12]||(s[12]=[i("https://opensource.com/article/20/11/nbde-linux",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=i("作者：",-1)),n(e,{href:"https://opensource.com/users/rcurtiswarfield"},{default:t(()=>[...s[14]||(s[14]=[i("Curt Warfield",-1)])]),_:1}),s[19]||(s[19]=i(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[15]||(s[15]=[i("lujun9972",-1)])]),_:1}),s[20]||(s[20]=i(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[16]||(s[16]=[i("geekpi",-1)])]),_:1}),s[21]||(s[21]=i(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[17]||(s[17]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[24]||(s[24]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[22]||(s[22]=[i("LCTT",-1)])]),_:1}),s[25]||(s[25]=i(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[23]||(s[23]=[i("Linux中國",-1)])]),_:1}),s[26]||(s[26]=i(" 榮譽推出",-1))])])}const C=l(h,[["render",g]]);export{m as __pageData,C as default};
